    var note = el('div', 'vip-note');
    note.appendChild(svgIcon('lock', 13));
    note.appendChild(el('span', null,
      'الاشتراك والتحقق والتسليم تتم داخل بوت Escuila — التطبيق والبوت نظام واحد'));
    viewEl.appendChild(note);
